'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Header from '@/components/Header';
import Sidebar from '@/components/Sidebar';
import Dashboard from '@/components/Dashboard';
import Projects from '@/components/Projects';
import Clients from '@/components/Clients';
import Users from '@/components/Users';
import Archive from '@/components/Archive';

export default function Home() {
  const router = useRouter();
  const [currentSection, setCurrentSection] = useState('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [session, setSession] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      router.push('/login');
      return;
    }
    try {
      const sess = JSON.parse(localStorage.getItem('user_session') || '{}');
      setSession(sess);
    } catch {
      setSession({});
    }
    setLoading(false);
  }, [router]);

  if (loading) return null;

  const isAdmin = session.role === 'admin' || !session.role;

  return (
    <div>
      <Header
        username={session.name || 'Username'}
        searchTerm={searchTerm}
        setSearchTerm={setSearchTerm}
      />
      <div className="layout">
        <Sidebar
          currentSection={currentSection}
          setCurrentSection={setCurrentSection}
          isAdmin={isAdmin}
        />
        <main className="main-content">
          {currentSection === 'dashboard' && <Dashboard isAdmin={isAdmin} />}
          {currentSection === 'projects' && (
            <Projects isAdmin={isAdmin} searchTerm={searchTerm} />
          )}
          {currentSection === 'archive' && <Archive isAdmin={isAdmin} />}
          {currentSection === 'clients' && isAdmin && <Clients />}
          {currentSection === 'users' && isAdmin && (
            <Users currentUserId={session.id} />
          )}
        </main>
      </div>
    </div>
  );
}


import { useEffect, useState } from 'react';

const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000';

export default function Page() {
    useEffect(() => {
        fetch(`${API_URL}/api/health`)
            .then(res => res.json())
            .then(data => console.log(data));
    }, []);

    return <div>Dashboard</div>;
}